void analyzeReviewsParallel(const std::vector<std::string>& reviews, size_t numThreads) {
    if (reviews.empty() || numThreads <= 0) return;

    size_t batchSize = reviews.size() / numThreads; // Number of reviews per thread
    size_t remaining = reviews.size() % numThreads; // Remaining reviews to distribute

    std::vector<std::thread> threads;
    for (size_t i = 0; i < numThreads; ++i) {
        size_t start = i * batchSize + std::min(i, remaining); // Calculate starting index
        size_t end = (i + 1) * batchSize + std::min(i + 1, remaining); // Calculate ending index
        threads.emplace_back(std::thread(analyzeReview, std::string(reviews.begin() + start, reviews.begin() + end)));
    }

    for (auto& t : threads) {
        if (t.joinable()) {
            t.join();
        }
    }
}

