    std::vector<std::string> reviews = {"Great product!", "Terrible quality.", "Excellent service!", "Not satisfied."};

    // Number of threads to use
    size_t numThreads = std::thread::hardware_concurrency(); // Use all available cores

    // Analyze reviews in parallel
    analyzeReviewsParallel(reviews, numThreads);

    return 0;
}
