#define WM8731_I2C_ADDR 0x1A  // WM8731 I2C address
#define WM8731_REG_VOL_L 0x00 // Volume register for left channel
#define WM8731_REG_VOL_R 0x01 // Volume register for right channel

uint8_t I2C_Write(uint16_t DevAddr, uint8_t RegAddr, uint8_t *pData, uint16_t Length) {
    return HAL_I2C_Master_Transmit(I2C1, DevAddr << 1, &RegAddr, 1, 1000) &&
           HAL_I2C_Master_Transmit(I2C1, DevAddr << 1 | 0x01, pData, Length, 1000);
}

void SetVolume(uint8_t left_vol, uint8_t right_vol) {
    uint8_t data[2];

    // Pack the volume levels into a byte array
    data[0] = (left_vol & 0xFF);  // MSB of left volume
    data[1] = (right_vol & 0xFF); // MSB of right volume

    // Write to the WM8731's volume registers
    I2C_Write(WM8731_I2C_ADDR, WM8731_REG_VOL_L, data + 0, 1); // Write to left volume register
    I2C_Write(WM8731_I2C_ADDR, WM8731_REG_VOL_R, data + 1, 1); // Write to right volume register
}

