import axios from 'axios';

// Configuration
const clientId = 'your-client-id';
const clientSecret = 'your-client-secret';
const sandboxUrl = 'https://your-sandbox-subdomain.commercecloud.salesforce.com'; // Replace with your sandbox URL

// Helper function to get access token
async function getAccessToken(): Promise<string> {
    const response = await axios.post(`${sandboxUrl}/oauth/token`, {
        grant_type: 'client_credentials',
        client_id: clientId,
        client_secret: clientSecret
    }, {
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
        }
    });

    return response.data.access_token;
}

// Helper function to make authenticated requests
async function makeRequest(url: string, method: 'GET' | 'POST' | 'PUT' | 'DELETE', data?: any): Promise<any> {
    const accessToken = await getAccessToken();
    const headers = {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
    };

    const instance = axios.create({
        baseURL: url,
        headers: headers
    });

    let requestConfig = {
        method: method,
        headers: headers
    };

    if (data) {
        requestConfig.data = JSON.stringify(data);
    }

    try {
        const response = await instance.request(requestConfig);
        return response.data;
    } catch (error) {
        console.error('Error making API request:', error.response ? error.response.data : error.message);
        throw error;
    }
}

// Example: Get a product from Salesforce Commerce Cloud
async function getProduct(productId: string): Promise<any> {
    const response = await makeRequest(`${sandboxUrl}/c/merchant/api/products/v2/${productId}`, 'GET');
    return response;
}

// Example: Create an order
async function createOrder(orderData: any): Promise<any> {
    const response = await makeRequest(`${sandboxUrl}/c/merchant/api/orders/v2`, 'POST', orderData);
