const MyCustomBlockEdit = (props) => {
    const { clientId } = props;
    const { setAttributes } = props;

    // Function to handle focus event
    const handleFocus = () => {
        console.log('The block has gained focus.');
        // Perform any action you need when the block gains focus
    };

    // Add the focus event listener
    props.attributes.focusEvent ? window.addEventListener('focus', handleFocus) : '';

    return (
        <Fragment>
            {/* Render your block content here */}
            <div className="my-custom-block">
                <p>{__('Hello, this is my custom block!')}</p>
            </div>
        </Fragment>
    );
};

