First, make sure you have the `System.Text.Json` namespace available. Here's a complete example:

```csharp
using System;
using System.Text;

public class Painting
{
    public string Title { get; set; }
    public string Artist { get; set; }
    public string Year { get; set; }
}

public class Program
{
    public static void Main()
    {
        // Create an instance of the Painting class with the required data
        Painting painting = new Painting
        {
            Title = "The Starry Night",
            Artist = "Vincent van Gogh",
            Year = "1889"
        };

        // Format the data into a JSON object
        var json = FormatToJson(painting);

        // Print the JSON output
        Console.WriteLine(json);
    }

    private static string FormatToJson(Painting painting)
    {
        StringBuilder stringBuilder = new StringBuilder();
        stringBuilder.Append("{");
        stringBuilder.AppendLine($"\"painting\": {{");
        stringBuilder.AppendLine($"\"title\": \"{painting.Title}\",");
        stringBuilder.AppendLine($"\"artist\": \"{painting.Artist}\",");
        stringBuilder.AppendLine($"\"year\": \"{painting.Year}\"");
        stringBuilder.AppendLine("}}");

        return stringBuilder.ToString();
    }
}
```

